}
task.spawn(function()
  local buf=table.create(4)
  for i=1,4 do buf[i]=__xor(__b64decode(__PARTS[i]),__KEY); __PARTS[i]=nil; task.wait() end
  local s=table.concat(buf); table.clear(buf)
